import React, { useState } from 'react';
import { api } from '../api';
import { useNavigate } from 'react-router-dom';
import './RegisterPage.scss';

const RegisterPage = () => {
    const [form, setForm] = useState({ username: '', password: '' });
    const navigate = useNavigate();

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            await api.registerUser(form);
            alert("Account created! You can now login.");
            navigate('/login');
        } catch (err) {
            alert("Registration failed");
        }
    };

    return (
        <div className="page"> {/* Added wrapper to match your .page style */}
            <header className="header">
                <div className="header__inner">
                    <div className="brand">FLOWER SHOP</div>
                </div>
            </header>

            <main className="main">
                <div className="container">
                    {/* Using your .modal and .card styles for the form box */}
                    <div className="modal" style={{ margin: '0 auto', backdropFilter: 'blur(10px)' }}>
                        <div className="modal__header">
                            <h2 className="modal__title">Register New Account</h2>
                        </div>

                        <form onSubmit={handleSubmit} className="form" style={{ padding: '24px', display: 'flex', flexDirection: 'column', gap: '15px' }}>
                            <div className="label">
                                Username
                                <input 
                                    type="text" 
                                    className="input" // Using your .input class
                                    placeholder="Enter username" 
                                    onChange={e => setForm({...form, username: e.target.value})} 
                                    required
                                />
                            </div>

                            <div className="label">
                                Password
                                <input 
                                    type="password" 
                                    className="input" // Using your .input class
                                    placeholder="Enter password" 
                                    onChange={e => setForm({...form, password: e.target.value})} 
                                    required
                                />
                            </div>

                            <div className="modal__actions">
                                <button type="submit" className="btn btn--primary" style={{ width: '100%' }}>
                                    Create Account
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            </main>
        </div>
    );
};

export default RegisterPage;
